package com.portfoliolab.backend.research;
import org.junit.jupiter.api.Test;import java.time.*;import java.math.*;import java.util.*;import com.portfoliolab.backend.asset.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ResearchServiceTests {
 ResearchHistoryStore.Candle candle(String day,String close){var n=new BigDecimal(close);return new ResearchHistoryStore.Candle(Instant.parse(day+"T00:00:00Z"),n,n,n,n,100);}
 @Test void boundsRejectBeforeDatabaseAccess(){var assets=mock(AssetRepository.class);var store=mock(ResearchHistoryStore.class);var service=new ResearchService(assets,store);assertThrows(RuntimeException.class,()->service.research(1,LocalDate.of(2024,1,1),LocalDate.of(2024,2,1),14));verifyNoInteractions(assets,store);}
 @Test void gapsRestartWarmupAndSummaryComesFromStoredCandles(){var assets=mock(AssetRepository.class);var store=mock(ResearchHistoryStore.class);var asset=new Asset("ALPHA","Fictional",BigDecimal.TEN,"INR");when(assets.findById(1L)).thenReturn(Optional.of(asset));var from=LocalDate.of(2026,1,1);var to=from.plusDays(5);when(store.read(1,from,to)).thenReturn(List.of(candle("2026-01-01","100"),candle("2026-01-02","110"),candle("2026-01-04","120"),candle("2026-01-05","130")));doThrow(new IllegalStateException()).when(store).ingest(1,"ALPHA",from,to);var r=new ResearchService(assets,store).research(1,from,to,2);assertEquals(1,r.missingDays());assertNull(r.bars().get(2).indicators().sma());assertEquals(0,r.summary().changePct().compareTo(new BigDecimal("30")));assertFalse(r.warnings().isEmpty());}
 @Test void completeCacheAvoidsGoAndDatabaseMutation(){var assets=mock(AssetRepository.class);var store=mock(ResearchHistoryStore.class);when(assets.findById(1L)).thenReturn(Optional.of(new Asset("ALPHA","Fictional",BigDecimal.TEN,"INR")));var from=LocalDate.of(2026,1,1);var to=from.plusDays(2);when(store.read(1,from,to)).thenReturn(List.of(candle("2026-01-01","100"),candle("2026-01-02","110")));var r=new ResearchService(assets,store).research(1,from,to,2);assertEquals(0,r.missingDays());verify(store,never()).ingest(anyLong(),anyString(),any(),any());}
}
